package com.aluba.travelrecorder;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.location.*;
import android.media.*;
import android.net.*;
import android.os.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** Runs against production classes in a disposable Android emulator, not a stub JVM. */
public final class DeviceChecks extends Instrumentation {
 TravelApplication app;int checks;File out;StringBuilder log=new StringBuilder();
 void check(boolean b,String label){android.util.Log.i("TravelChecks",(b?"PASS ":"FAIL ")+label);checks++;log.append((b?"PASS ":"FAIL ")+label+"\n");if(!b)throw new AssertionError(label);}
 interface Condition{boolean get()throws Exception;}
 void until(Condition c,long timeout)throws Exception{long end=System.currentTimeMillis()+timeout;while(!c.get()){if(System.currentTimeMillis()>end)throw new AssertionError("Timed out");Thread.sleep(30);}}
 void work(TravelApplication.Work w)throws Exception{CountDownLatch done=new CountDownLatch(1);AtomicReference<Throwable> error=new AtomicReference<>();app.worker.execute(()->{try{w.run();}catch(Throwable e){error.set(e);}finally{done.countDown();}});if(!done.await(15,TimeUnit.SECONDS))throw new AssertionError("worker timed out");if(error.get()!=null)throw new RuntimeException(error.get());}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();try{app=(TravelApplication)getTargetContext().getApplicationContext();out=new File(app.getExternalFilesDir(null),"checks");out.mkdirs();until(()->app.ready,10000);app.getSharedPreferences("prefs",0).edit().putBoolean("autoPhotos",false).commit();
  android.util.Log.i("TravelChecks","starting activity");MainActivity activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));android.util.Log.i("TravelChecks","activity started");waitForIdleSync();android.util.Log.i("TravelChecks","idle reached");
  runOnMainSync(()->{activity.nav.getChildAt(1).performClick();check(activity.heading.getText().toString().equals("回忆"),"cold navigation to memories before recording");activity.nav.getChildAt(2).performClick();check(activity.heading.getText().toString().equals("设置"),"cold navigation to settings before recording");activity.nav.getChildAt(0).performClick();});
  Models.Trip trip=new Models.Trip(System.currentTimeMillis()-600000);trip.title="西湖漫步 · 测试";trip.features="沿湖散步，记录一路的风景。";trip.from="西湖";trip.to="湖滨";trip.status=2;trip.end=System.currentTimeMillis();List<RouteMath.Point> points=new ArrayList<>();
  for(int i=0;i<60;i++){double angle=i/59.0*Math.PI*1.7;points.add(new RouteMath.Point(30.24+Math.sin(angle)*.008,120.14+Math.cos(angle)*.009,trip.start+i*9000,5,i<32?0:1));}
  work(()->{app.db.save(trip);for(RouteMath.Point p:points)app.db.addPoint(trip,p);app.publish();});check(app.state.points(trip.id).size()==60,"real SQLite route persists all timestamps and segments");
  List<Models.Photo> photos=new ArrayList<>();for(int i=0;i<3;i++){Bitmap b=Bitmap.createBitmap(800,600,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.drawColor(new int[]{0xFF78BE8B,0xFF94BDEB,0xFFFFC269}[i]);android.graphics.Paint paint=new android.graphics.Paint(3);paint.setColor(Color.WHITE);paint.setTextSize(58);c.drawText("Travel "+(i+1),100,300,paint);File source=new File(out,"source"+i+".jpg");Photos.write(b,source);b.recycle();ExifInterface exif=new ExifInterface(source.getPath());RouteMath.Point point=points.get(10+i*15);exif.setAttribute(ExifInterface.TAG_GPS_LATITUDE,gps(point.lat));exif.setAttribute(ExifInterface.TAG_GPS_LATITUDE_REF,"N");exif.setAttribute(ExifInterface.TAG_GPS_LONGITUDE,gps(point.lon));exif.setAttribute(ExifInterface.TAG_GPS_LONGITUDE_REF,"E");exif.setAttribute(ExifInterface.TAG_DATETIME_ORIGINAL,"2026:10:24 10:20:30");exif.saveAttributes();Models.Photo p=app.photos.prepare(Uri.fromFile(source),trip.id,point.time,false);photos.add(p);check(p.lat!=null&&Math.abs(p.lat-point.lat)<0.00001,"photo EXIF location imported "+i);check(new File(app.getFilesDir(),p.thumb).isFile(),"independent thumbnail persisted "+i);work(()->app.db.save(p));}
  Models.Diary diary=new Models.Diary();diary.trip=trip.id;diary.photo=photos.get(0).id;diary.time=trip.start;diary.lat=points.get(10).lat;diary.lon=points.get(10).lon;diary.title="湖边";diary.text="微风和树影。";work(()->{app.db.save(diary);app.publish();});app.favorite(trip.id,"",true);work(()->{});check(app.state.trip(trip.id).favorite>0&&app.state.trip(trip.id).reason.isEmpty(),"favorite with optional empty reason persists");check(app.state.diaries(trip.id).get(0).text.equals("微风和树影。"),"diary persistence");
  File poster=ShareExporter.export(app,trip,points,photos,trip.features,false,new AtomicBoolean(),p->{});Bitmap image=BitmapFactory.decodeFile(poster.getPath());check(image.getWidth()==640&&image.getHeight()>=960,"production JPEG poster dimensions");image.recycle();check("TravelRecorder Share".equals(new ExifInterface(poster.getPath()).getAttribute(ExifInterface.TAG_SOFTWARE)),"generated JPEG excluded from automatic reimport");copy(poster,new File(out,"share-preview.jpg"));
  File video=ShareExporter.export(app,trip,points,photos,trip.features,true,new AtomicBoolean(),p->{});MediaMetadataRetriever metadata=new MediaMetadataRetriever();metadata.setDataSource(video.getPath());long duration=Long.parseLong(metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));check(duration>=19000&&duration<=61000,"real Android H264 encode duration");check("640".equals(metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)),"real encoded video width");Bitmap frame=metadata.getFrameAtTime(duration*500,MediaMetadataRetriever.OPTION_CLOSEST);check(frame!=null,"video decodes a real middle frame");if(frame!=null){Photos.write(frame,new File(out,"video-frame.jpg"));frame.recycle();}metadata.release();copy(video,new File(out,"share-preview.mp4"));
  runOnMainSync(()->activity.saveGallery(poster));
  until(()->{try(android.database.Cursor c=app.getContentResolver().query(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,new String[]{"_id"},"_display_name=?",new String[]{poster.getName()},null)){return c!=null&&c.moveToFirst();}},8000);
  check(true,"generated poster saved via Android MediaStore");
  Uri shared=ShareProvider.uri(poster);try(InputStream in=app.getContentResolver().openInputStream(shared)){check(in!=null&&in.read()==255,"share provider serves granted JPEG");}boolean denied=false;try{app.getContentResolver().openFileDescriptor(Uri.parse("content://com.aluba.travelrecorder.share/../travel.sqlite"),"r");}catch(Exception e){denied=true;}check(denied,"share provider rejects traversal");boolean writeDenied=false;try{app.getContentResolver().openFileDescriptor(shared,"w");}catch(Exception e){writeDenied=true;}check(writeDenied,"share provider rejects writes");
  work(()->{app.db.deletePhoto(photos.get(0));app.publish();});check(app.state.photos(trip.id).size()==2,"photo metadata removed");check(app.state.diaries(trip.id).get(0).photo.isEmpty(),"photo removal preserves associated diary");check(new File(out,"source0.jpg").isFile(),"original photo preserved");
  runOnMainSync(()->{activity.tab=1;activity.detail=null;activity.showPage();});waitForIdleSync();Thread.sleep(500);Bitmap screen=getUiAutomation().takeScreenshot();Photos.write(screen,new File(out,"memories-screen.jpg"));screen.recycle();
  // Foreground service is started from the visible activity; location is injected via OS test provider.
  runOnMainSync(()->{activity.tab=0;activity.detail=null;activity.showPage();activity.startRecording();});until(()->app.state.active()!=null&&app.state.active().status==0,5000);
  LocationManager locations=(LocationManager)app.getSystemService(Context.LOCATION_SERVICE);locations.addTestProvider(LocationManager.GPS_PROVIDER,false,false,false,false,true,true,true,Criteria.POWER_LOW,Criteria.ACCURACY_FINE);locations.setTestProviderEnabled(LocationManager.GPS_PROVIDER,true);Thread.sleep(200);
  Location l=new Location(LocationManager.GPS_PROVIDER);l.setLatitude(30.24);l.setLongitude(120.14);l.setAccuracy(5);l.setTime(System.currentTimeMillis());l.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());locations.setTestProviderLocation(LocationManager.GPS_PROVIDER,l);
  String active=app.state.active().id;until(()->!app.state.points(active).isEmpty(),5000);check(!app.state.points(active).isEmpty(),"foreground service accepts actual OS location callback");
  runOnMainSync(()->activity.command(RecordingService.PAUSE));until(()->app.state.trip(active).status==1,5000);check(app.state.trip(active).status==1,"pause persists and stops service");until(()->!RecordingService.alive,5000);
  runOnMainSync(()->activity.startRecording());until(()->app.state.trip(active).status==0,5000);Thread.sleep(300);l.setLongitude(120.15);l.setTime(System.currentTimeMillis());l.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());locations.setTestProviderLocation(LocationManager.GPS_PROVIDER,l);until(()->app.state.points(active).size()>=2,5000);List<RouteMath.Point> actual=app.state.points(active);check(actual.get(0).segment!=actual.get(actual.size()-1).segment&&app.state.trip(active).distance==0,"resume gap neither joined nor added to distance");
  runOnMainSync(()->{activity.startReplay();activity.cursor=actual.get(actual.size()-1).time;activity.replayTick();check(activity.live,"recording replay catches up into live state");});
  Thread.sleep(2200); // Respect the production GPS subscription minimum interval.
  l.setLongitude(120.1502);l.setTime(System.currentTimeMillis());l.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());locations.setTestProviderLocation(LocationManager.GPS_PROVIDER,l);until(()->app.state.points(active).size()>=3,5000);
  runOnMainSync(()->{activity.replayTick();check(activity.map.replay!=null&&Math.abs(activity.map.replay.lon-120.1502)<0.000001,"live replay reaches newly recorded position");activity.map.cx=0;activity.map.cy=0;activity.camera=true;activity.updateReplay();check(activity.map.cx==0,"offscreen replay starts without teleporting");activity.map.stepCamera(1.0/60);double first=activity.map.cx;check(first!=0&&Math.abs(RouteMath.delta(RouteMath.x(120.1502)-first))>.01,"camera moves partway on first frame");for(int frameIndex=0;frameIndex<900;frameIndex++)activity.map.stepCamera(1.0/60);check(Math.abs(activity.map.sx(120.1502)-activity.map.getWidth()/2f)<1,"smooth replay camera converges on red point");activity.map.targetCamera(121,31);activity.map.stopCamera();double stopped=activity.map.cx;activity.map.stepCamera(.1);check(activity.map.cx==stopped,"manual camera stop cancels pending motion");activity.stopReplay();});
  runOnMainSync(()->{activity.map.follow=false;activity.refresh();check(!activity.map.follow,"GPS refresh preserves manual map browsing");activity.command(RecordingService.FINISH);});until(()->app.state.trip(active).status==2,5000);locations.removeTestProvider(LocationManager.GPS_PROVIDER);
  work(()->{app.db.deleteTrip(active);app.publish();});check(app.state.trip(active)==null&&app.state.points(active).isEmpty(),"trip deletion removes route records");
  result.putString("status","PASS");result.putInt("checks",checks);result.putString("output",out.getPath());finish(Activity.RESULT_OK,result);
 }catch(Throwable e){log.append(android.util.Log.getStackTraceString(e));result.putString("status","FAIL");result.putString("error",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{try{if(out!=null)try(FileOutputStream f=new FileOutputStream(new File(out,"checks.log"))){f.write(log.toString().getBytes("UTF-8"));}}catch(Exception ignored){}}}
 static String gps(double value){int degrees=(int)value;double m=(value-degrees)*60;int minutes=(int)m;long seconds=Math.round((m-minutes)*60*1000000);return degrees+"/1,"+minutes+"/1,"+seconds+"/1000000";}
 static void copy(File from,File to)throws IOException{try(InputStream in=new FileInputStream(from);OutputStream out=new FileOutputStream(to)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}}
}
